const documentedCapacityGaps = new Set([
  "aquawing-aqa3000",
  "haqos-easy-1000at","haqos-aqua-flow-250",
  "nubios-yu118c","nubios-yu119c",
]);
for(const item of equipmentCatalog){
  if(documentedCapacityGaps.has(item.id)&&!item.capacityDataNote)item.capacityDataNote="Üretici ve incelenen güvenilir satıcı kaynaklarında kapasite/debi değeri yayımlanmamış; tahmini değer kullanılmıyor.";
}

const hasCapacityData = (profile:EquipmentProfile) => {
  if(profile.category==="heater")return Boolean(profile.powerW||profile.recommendedMinL||profile.recommendedMaxL);
  if(profile.category==="filter")return Boolean(profile.ratedFlowLph||profile.recommendedMaxL||profile.requiresAirPump);
  if(profile.category==="air_pump")return Boolean(profile.ratedFlowLph);
  return true;
};

function assertUniqueEquipmentModels(items:EquipmentProfile[]){const seen=new Set<string>();for(const item of items){const key=[item.category,item.brand,item.model].map(value=>value.trim().toLocaleLowerCase("tr-TR")).join("|");if(seen.has(key))throw new Error(`Ekipman kataloğunda yinelenen kategori/marka/model: ${item.category} / ${item.brand} / ${item.model}`);seen.add(key)}}
// Bütünlük denetimi geliştirmede, testlerde ve CI'da (`pnpm verify`) çalışır; üretim derlemesinde kullanıcının tarayıcısında çalışmaz (docs/DECISIONS/0015-katalog-modulleri-ve-sayfa-hizi.md).
function assertEquipmentCatalogIntegrity(){
  assertUniqueIds("Ekipman",equipmentCatalog);assertUniqueEquipmentModels(equipmentCatalog);
  const unverifiedEquipmentIds:string[]=[];
  for(const item of equipmentCatalog){
    for(const value of [item.ratedFlowLph,item.powerW,item.recommendedMinL,item.recommendedMaxL,item.integratedHeaterW,item.integratedUvcW])if(value!==undefined&&value<=0)throw new Error(`Geçersiz ekipman sayısal değeri: ${item.id}`);
    if(item.recommendedMinL&&item.recommendedMaxL&&item.recommendedMinL>item.recommendedMaxL)throw new Error(`Ters ekipman hacim aralığı: ${item.id}`);
    if(item.recommendedTankLengthCm&&(item.recommendedTankLengthCm[0]<=0||item.recommendedTankLengthCm[0]>item.recommendedTankLengthCm[1]))throw new Error(`Geçersiz ekipman uzunluk aralığı: ${item.id}`);
    if(Boolean(item.sourceUrl)!==Boolean(item.verifiedAt))throw new Error(`Eksik ekipman kaynak/tarih çifti: ${item.id}`);
    if(!hasCapacityData(item)&&!item.capacityDataNote)throw new Error(`Açıklanmamış ekipman kapasite boşluğu: ${item.id}`);
    if(hasCapacityData(item)&&item.capacityDataNote)throw new Error(`Teknik verisi bulunan ekipmanda gereksiz kapasite notu: ${item.id}`);
    if(!item.sourceUrl||!item.verifiedAt||item.specifications.toLocaleLowerCase("tr-TR").includes("doğrulama bekliyor"))unverifiedEquipmentIds.push(item.id);
  }
  if(unverifiedEquipmentIds.length)throw new Error(`Doğrulanmamış ekipman kayıtları: ${unverifiedEquipmentIds.join(", ")}`);
}
if(process.env.NODE_ENV!=="production")assertEquipmentCatalogIntegrity();

// Arama dizini (docs/DECISIONS/0015-katalog-modulleri-ve-sayfa-hizi.md): katalog kimliği olmayan bir ekipman için eski arama
// 3500'ü aşan kaydın marka ve model adını her çağrıda yeniden biçimlendiriyordu. Katalog çalışma sırasında değişmez; anahtarlar
// ilk kullanımda bir kez hesaplanır. Sonuçlar eski aramalarla birebir aynıdır: eşleşme varsa katalog sırasındaki ilk kayıt döner.
// Kimlik dizini biçimlendirme gerektirmediği için ayrı tutulur; marka/model dizini yalnızca kimliği olmayan bir kayıt geldiğinde kurulur.
let equipmentByIdCache: Map<string, EquipmentProfile> | undefined;
function equipmentByIdIndex() {
  if (equipmentByIdCache) return equipmentByIdCache;
  equipmentByIdCache = new Map();
  for (const profile of equipmentCatalog) if (!equipmentByIdCache.has(profile.id)) equipmentByIdCache.set(profile.id, profile);
  return equipmentByIdCache;
}
let equipmentByBrandModelCache: Map<string, EquipmentProfile> | undefined;
const brandModelKey = (brand: string, model: string) => `${brand}\u0000${model}`;
function equipmentByBrandModelIndex() {
  if (equipmentByBrandModelCache) return equipmentByBrandModelCache;
  equipmentByBrandModelCache = new Map();
  for (const profile of equipmentCatalog) {
    const key = brandModelKey(normalize(profile.brand) ?? "", normalize(profile.model) ?? "");
    if (!equipmentByBrandModelCache.has(key)) equipmentByBrandModelCache.set(key, profile);
  }
  return equipmentByBrandModelCache;
}
export const equipmentById = (id?: string) => id === undefined ? undefined : equipmentByIdIndex().get(id);
export const equipmentForCategory = (category: Equipment["category"]) => equipmentCatalog.filter(item=>item.category===category);
export const equipmentBrandsForCategory = (category: Equipment["category"]) => [...new Set(equipmentForCategory(category).map(item=>item.brand))].sort((a,b)=>a.localeCompare(b,"tr"));
export const equipmentForBrandInCategory = (category: Equipment["category"], brand: string) => equipmentForCategory(category).filter(item=>item.brand===brand);
export const isVerifiedEquipmentProfile = (profile?: EquipmentProfile): profile is EquipmentProfile => Boolean(profile?.sourceUrl&&profile?.verifiedAt&&!profile.specifications.toLocaleLowerCase("tr-TR").includes("doğrulama bekliyor"));
export const hasStandaloneCapacityData = (profile?: EquipmentProfile) => {
  return profile?hasCapacityData(profile):false;
};
// Katalog kimliği yoksa marka ve model adı birlikte eşleşmelidir; ikisinden biri eksikse eşleşme yoktur.
export const profileForEquipment = (item: Equipment) => {
  const profile = equipmentById(item.catalogId);
  if (profile) return profile;
  const brand = normalize(item.brand), model = normalize(item.model);
  return brand === undefined || model === undefined ? undefined : equipmentByBrandModelIndex().get(brandModelKey(brand, model));
};
